export const logout = <ThrowOnError extends boolean = false>(
  options?: Options<LogoutData, ThrowOnError>,
): RequestResult<LogoutResponses, LogoutErrors, ThrowOnError> =>
  (options?.client ?? client).delete<LogoutResponses, LogoutErrors, ThrowOnError>({
    security: [
      {
        key: 'staffBearerAuth',
        scheme: 'bearer',
        type: 'http',
      },
    ],
    url: '/api/admin/auth/sessions/current',
    ...options,
  });
